module ActiveSupport;module RangeWithFormat;RANGE_FORMATS={db:->(start,stop) do if start&&stop;case start;when String then "BETWEEN '#{start}' AND '#{stop}'";else "BETWEEN '#{start.to_fs(:db)}' AND '#{stop.to_fs(:db)}'";end;elsif start;case start;when String then ">= '#{start}'";else ">= '#{start.to_fs(:db)}'";end;elsif stop;case stop;when String then "<= '#{stop}'";else "<= '#{stop.to_fs(:db)}'";end;end;end};def to_fs(format=:default)if formatter=RANGE_FORMATS[format];formatter.call(self.begin,self.end);else to_s;end;end;alias_method:to_formatted_s,:to_fs;end;end;Range.prepend(ActiveSupport::RangeWithFormat)
